window.onload = function() {
  // Build a system
  let url = window.location.search.match(/url=([^&]+)/);
  if (url && url.length > 1) {
    url = decodeURIComponent(url[1]);
  } else {
    url = window.location.origin;
  }
  let options = {
  "swaggerDoc": {
    "openapi": "3.0.0",
    "paths": {
      "/map/api/v1/measurements/current": {
        "get": {
          "description": "Use measure query to specify and return only the desired measurement type",
          "operationId": "MeasurementController_getLastMeasurements",
          "parameters": [
            {
              "name": "measure",
              "required": false,
              "in": "query",
              "description": "Type of measurement to filter by",
              "schema": {
                "type": "string",
                "enum": [
                  "pm25",
                  "pm10",
                  "atmp",
                  "rhum",
                  "rco2",
                  "o3",
                  "no2"
                ]
              }
            },
            {
              "name": "page",
              "required": false,
              "in": "query",
              "schema": {
                "minimum": 1,
                "default": 1,
                "type": "number"
              }
            },
            {
              "name": "pagesize",
              "required": false,
              "in": "query",
              "schema": {
                "minimum": 1,
                "default": 100,
                "type": "number"
              }
            },
            {
              "name": "dataSources",
              "required": false,
              "in": "query",
              "description": "Optional datasource names from GET /map/api/v1/catalog/datasources. Enter one or more names as a comma-separated string, for example AirGradient,OpenAQ. Repeated query parameters are also accepted by the API. Valid values: AirGradient, AirQo, AirBKK, OpenAQ, DustBoy, SensorCommunity, BreatheLondon, CNEMC, Clarity. Omit this parameter, or pass it blank, to include all datasources.",
              "schema": {
                "example": "AirGradient,OpenAQ",
                "type": "string"
              }
            },
            {
              "name": "sensorTypes",
              "required": false,
              "in": "query",
              "description": "Optional sensor type names from GET /map/api/v1/catalog/sensor-types. Enter one or more names as a comma-separated string, for example Reference,Small Sensor. Repeated query parameters are also accepted by the API. Valid values: Reference, Small Sensor. Omit this parameter, or pass it blank, to include all sensor types.",
              "schema": {
                "example": "Reference,Small Sensor",
                "type": "string"
              }
            }
          ],
          "responses": {
            "200": {
              "description": "",
              "content": {
                "application/json": {
                  "schema": {
                    "allOf": [
                      {
                        "$ref": "#/components/schemas/Pagination"
                      },
                      {
                        "properties": {
                          "data": {
                            "type": "array",
                            "items": {
                              "$ref": "#/components/schemas/MeasurementEntity"
                            }
                          }
                        }
                      }
                    ]
                  }
                }
              }
            }
          },
          "summary": "Retrieves the current measurements from all locations",
          "tags": [
            "Measurements"
          ]
        }
      },
      "/map/api/v1/measurements/current/area": {
        "get": {
          "description": "X and Y query to determine bottom left and top right coordinate of digital maps; Use measure query to specify and return only the desired measurement type",
          "operationId": "MeasurementController_getLastMeasurementsByArea",
          "parameters": [
            {
              "name": "measure",
              "required": false,
              "in": "query",
              "description": "Type of measurement to filter by",
              "schema": {
                "type": "string",
                "enum": [
                  "pm25",
                  "pm10",
                  "atmp",
                  "rhum",
                  "rco2",
                  "o3",
                  "no2"
                ]
              }
            },
            {
              "name": "xmin",
              "required": true,
              "in": "query",
              "description": "West longitude (minimum longitude value) - leftmost boundary",
              "schema": {
                "example": -122.4194,
                "type": "number"
              }
            },
            {
              "name": "ymin",
              "required": true,
              "in": "query",
              "description": "South latitude (minimum latitude value) - bottom boundary",
              "schema": {
                "example": 37.7749,
                "type": "number"
              }
            },
            {
              "name": "xmax",
              "required": true,
              "in": "query",
              "description": "East longitude (maximum longitude value) - rightmost boundary",
              "schema": {
                "example": -122.4094,
                "type": "number"
              }
            },
            {
              "name": "ymax",
              "required": true,
              "in": "query",
              "description": "North latitude (maximum latitude value) - top boundary",
              "schema": {
                "example": 37.7849,
                "type": "number"
              }
            },
            {
              "name": "zoom",
              "required": true,
              "in": "query",
              "description": "Map zoom level for clustering (higher values = more detailed clustering)",
              "schema": {
                "example": 10,
                "type": "number"
              }
            },
            {
              "name": "dataSources",
              "required": false,
              "in": "query",
              "description": "Optional datasource names from GET /map/api/v1/catalog/datasources. Enter one or more names as a comma-separated string, for example AirGradient,OpenAQ. Repeated query parameters are also accepted by the API. Valid values: AirGradient, AirQo, AirBKK, OpenAQ, DustBoy, SensorCommunity, BreatheLondon, CNEMC, Clarity. Omit this parameter, or pass it blank, to include all datasources.",
              "schema": {
                "example": "AirGradient,OpenAQ",
                "type": "string"
              }
            },
            {
              "name": "sensorTypes",
              "required": false,
              "in": "query",
              "description": "Optional sensor type names from GET /map/api/v1/catalog/sensor-types. Enter one or more names as a comma-separated string, for example Reference,Small Sensor. Repeated query parameters are also accepted by the API. Valid values: Reference, Small Sensor. Omit this parameter, or pass it blank, to include all sensor types.",
              "schema": {
                "example": "Reference,Small Sensor",
                "type": "string"
              }
            }
          ],
          "responses": {
            "200": {
              "description": "",
              "content": {
                "application/json": {
                  "schema": {
                    "allOf": [
                      {
                        "$ref": "#/components/schemas/Pagination"
                      },
                      {
                        "properties": {
                          "data": {
                            "type": "array",
                            "items": {
                              "$ref": "#/components/schemas/MeasurementEntity"
                            }
                          }
                        }
                      }
                    ]
                  }
                }
              }
            }
          },
          "summary": "Retrieve the current measurements from all locations within a specific area",
          "tags": [
            "Measurements"
          ]
        }
      },
      "/map/api/v1/measurements/current/cluster": {
        "get": {
          "description": "X, Y and zoom query to determine bottom left and top right coordinate of digital maps; Measure query to define 'value' field value on response, default to 'pm25'",
          "operationId": "MeasurementController_getLastMeasurementsByCluster",
          "parameters": [
            {
              "name": "measure",
              "required": false,
              "in": "query",
              "description": "Type of measurement to filter by",
              "schema": {
                "type": "string",
                "enum": [
                  "pm25",
                  "pm10",
                  "atmp",
                  "rhum",
                  "rco2",
                  "o3",
                  "no2"
                ]
              }
            },
            {
              "name": "xmin",
              "required": true,
              "in": "query",
              "description": "West longitude (minimum longitude value) - leftmost boundary",
              "schema": {
                "example": -122.4194,
                "type": "number"
              }
            },
            {
              "name": "ymin",
              "required": true,
              "in": "query",
              "description": "South latitude (minimum latitude value) - bottom boundary",
              "schema": {
                "example": 37.7749,
                "type": "number"
              }
            },
            {
              "name": "xmax",
              "required": true,
              "in": "query",
              "description": "East longitude (maximum longitude value) - rightmost boundary",
              "schema": {
                "example": -122.4094,
                "type": "number"
              }
            },
            {
              "name": "ymax",
              "required": true,
              "in": "query",
              "description": "North latitude (maximum latitude value) - top boundary",
              "schema": {
                "example": 37.7849,
                "type": "number"
              }
            },
            {
              "name": "zoom",
              "required": true,
              "in": "query",
              "description": "Map zoom level for clustering (higher values = more detailed clustering)",
              "schema": {
                "example": 10,
                "type": "number"
              }
            },
            {
              "name": "minPoints",
              "required": false,
              "in": "query",
              "description": "Minimum number of location to form a cluster",
              "schema": {
                "example": 2,
                "type": "number"
              }
            },
            {
              "name": "radius",
              "required": false,
              "in": "query",
              "description": "Cluster radius, in pixels",
              "schema": {
                "example": 80,
                "type": "number"
              }
            },
            {
              "name": "maxZoom",
              "required": false,
              "in": "query",
              "description": "Maximum zoom level at which clusters are generated",
              "schema": {
                "example": 8,
                "type": "number"
              }
            },
            {
              "name": "excludeOutliers",
              "required": false,
              "in": "query",
              "description": "Exclude outliers from the measurement data or not",
              "schema": {
                "type": "boolean"
              }
            },
            {
              "name": "dataSources",
              "required": false,
              "in": "query",
              "description": "Optional datasource names from GET /map/api/v1/catalog/datasources. Enter one or more names as a comma-separated string, for example AirGradient,OpenAQ. Repeated query parameters are also accepted by the API. Valid values: AirGradient, AirQo, AirBKK, OpenAQ, DustBoy, SensorCommunity, BreatheLondon, CNEMC, Clarity. Omit this parameter, or pass it blank, to include all datasources.",
              "schema": {
                "example": "AirGradient,OpenAQ",
                "type": "string"
              }
            },
            {
              "name": "sensorTypes",
              "required": false,
              "in": "query",
              "description": "Optional sensor type names from GET /map/api/v1/catalog/sensor-types. Enter one or more names as a comma-separated string, for example Reference,Small Sensor. Repeated query parameters are also accepted by the API. Valid values: Reference, Small Sensor. Omit this parameter, or pass it blank, to include all sensor types.",
              "schema": {
                "example": "Reference,Small Sensor",
                "type": "string"
              }
            }
          ],
          "responses": {
            "200": {
              "description": "",
              "content": {
                "application/json": {
                  "schema": {
                    "allOf": [
                      {
                        "$ref": "#/components/schemas/Pagination"
                      },
                      {
                        "properties": {
                          "data": {
                            "type": "array",
                            "items": {
                              "$ref": "#/components/schemas/MeasurementCluster"
                            }
                          }
                        }
                      }
                    ]
                  }
                }
              }
            }
          },
          "summary": "Retrieve the current measurements from clustered locations within a specific area",
          "tags": [
            "Measurements"
          ]
        }
      },
      "/map/api/v1/locations": {
        "get": {
          "description": "Retrieve detailed information about all air quality monitoring locations including coordinates, owner info, and sensor specifications.",
          "operationId": "LocationController_getLocations",
          "parameters": [
            {
              "name": "page",
              "required": false,
              "in": "query",
              "schema": {
                "minimum": 1,
                "default": 1,
                "type": "number"
              }
            },
            {
              "name": "pagesize",
              "required": false,
              "in": "query",
              "schema": {
                "minimum": 1,
                "default": 100,
                "type": "number"
              }
            },
            {
              "name": "dataSources",
              "required": false,
              "in": "query",
              "description": "Optional datasource names from GET /map/api/v1/catalog/datasources. Enter one or more names as a comma-separated string, for example AirGradient,OpenAQ. Repeated query parameters are also accepted by the API. Valid values: AirGradient, AirQo, AirBKK, OpenAQ, DustBoy, SensorCommunity, BreatheLondon, CNEMC, Clarity. Omit this parameter, or pass it blank, to include all datasources.",
              "schema": {
                "example": "AirGradient,OpenAQ",
                "type": "string"
              }
            },
            {
              "name": "sensorTypes",
              "required": false,
              "in": "query",
              "description": "Optional sensor type names from GET /map/api/v1/catalog/sensor-types. Enter one or more names as a comma-separated string, for example Reference,Small Sensor. Repeated query parameters are also accepted by the API. Valid values: Reference, Small Sensor. Omit this parameter, or pass it blank, to include all sensor types.",
              "schema": {
                "example": "Reference,Small Sensor",
                "type": "string"
              }
            }
          ],
          "responses": {
            "200": {
              "description": "",
              "content": {
                "application/json": {
                  "schema": {
                    "allOf": [
                      {
                        "$ref": "#/components/schemas/Pagination"
                      },
                      {
                        "properties": {
                          "data": {
                            "type": "array",
                            "items": {
                              "$ref": "#/components/schemas/LocationEntity"
                            }
                          }
                        }
                      }
                    ]
                  }
                }
              }
            }
          },
          "summary": "Get all monitoring locations",
          "tags": [
            "Locations"
          ]
        }
      },
      "/map/api/v1/locations/{id}": {
        "get": {
          "description": "Retrieve comprehensive information for a single monitoring location by its unique identifier.",
          "operationId": "LocationController_getLocationById",
          "parameters": [
            {
              "name": "id",
              "required": true,
              "in": "path",
              "description": "Unique location identifier",
              "schema": {
                "example": 12345,
                "type": "number"
              }
            }
          ],
          "responses": {
            "200": {
              "description": "Location details successfully retrieved",
              "content": {
                "application/json": {
                  "schema": {
                    "$ref": "#/components/schemas/LocationEntity"
                  }
                }
              }
            },
            "400": {
              "description": "Invalid location ID format"
            },
            "404": {
              "description": "Location not found"
            }
          },
          "summary": "Get specific location details",
          "tags": [
            "Locations"
          ]
        }
      },
      "/map/api/v1/locations/{id}/measures/current": {
        "get": {
          "description": "Retrieve the most recent air quality measurements for a specific monitoring location.",
          "operationId": "LocationController_getLastmeasuresByLocationId",
          "parameters": [
            {
              "name": "id",
              "required": true,
              "in": "path",
              "description": "Location identifier",
              "schema": {
                "example": 12345,
                "type": "number"
              }
            }
          ],
          "responses": {
            "200": {
              "description": "Latest measurements successfully retrieved",
              "content": {
                "application/json": {
                  "schema": {
                    "$ref": "#/components/schemas/LocationMeasures"
                  }
                }
              }
            },
            "404": {
              "description": "Location not found or no recent measurements available"
            }
          },
          "summary": "Get latest measurements for a location",
          "tags": [
            "Locations"
          ]
        }
      },
      "/map/api/v1/locations/{id}/cigarettes/smoked": {
        "get": {
          "description": "Calculates the equivalent number of cigarettes smoked based on PM2.5 exposure levels for different time periods. Uses the Berkeley Earth conversion: 22 μg/m³ PM2.5 = 1 cigarette per day. Returns flat object for default timeframes (backward compatible), or structured array for custom timeframes.",
          "operationId": "LocationController_getCigarettesSmoked",
          "parameters": [
            {
              "name": "id",
              "required": true,
              "in": "path",
              "description": "Location identifier",
              "schema": {
                "example": 12345,
                "type": "number"
              }
            },
            {
              "name": "timeframes",
              "required": false,
              "in": "query",
              "description": "Comma-separated string of timeframes in days. Format: number + \"d\" (days only). Examples: \"1d\", \"7d\", \"30d\", \"365d\". If omitted, returns default timeframes (1d, 7d, 30d, 365d).",
              "schema": {
                "example": "1d,7d,14d,30d",
                "type": "string"
              }
            }
          ],
          "responses": {
            "200": {
              "description": "Cigarette equivalents for multiple time periods. Returns flat object for default timeframes (backward compatible), or structured array for custom timeframes.",
              "content": {
                "application/json": {
                  "schema": {
                    "oneOf": [
                      {
                        "$ref": "#/components/schemas/CigarettesSmokedDto"
                      },
                      {
                        "$ref": "#/components/schemas/CigarettesArrayDto"
                      }
                    ]
                  }
                }
              }
            },
            "400": {
              "description": "Invalid location ID format or timeframe format"
            },
            "404": {
              "description": "Location not found or no PM2.5 data available"
            }
          },
          "summary": "Get cigarettes equivalent for air pollution exposure",
          "tags": [
            "Locations"
          ]
        }
      },
      "/map/api/v1/locations/{id}/averages": {
        "get": {
          "description": "Calculate average values for a specified \n    measurement type across different time periods (6h, \n    24h, 7d, 30d, 90d) for a specific location. Returns \n    null for periods with insufficient data. Defaults to\n    PM2.5 if measure is not specified.",
          "operationId": "LocationController_getLocationMeasurementAverages",
          "parameters": [
            {
              "name": "id",
              "required": true,
              "in": "path",
              "description": "Location identifier",
              "schema": {
                "example": 12345,
                "type": "number"
              }
            },
            {
              "name": "measure",
              "required": false,
              "in": "query",
              "description": "Type of measurement to filter by",
              "schema": {
                "type": "string",
                "enum": [
                  "pm25",
                  "pm10",
                  "atmp",
                  "rhum",
                  "rco2",
                  "o3",
                  "no2"
                ]
              }
            },
            {
              "name": "periods",
              "required": false,
              "in": "query",
              "description": "Comma-separated string of time periods. Format: number + time unit. Units: m (minutes), h (hours), d (days), w (weeks). Minimum period: 15 minutes. Examples: \"15m\", \"2h\", \"13d\", \"1w\". Recommended periods: 6h, 24h, 7d, 30d, 90d. If omitted, returns default periods (6h, 24h, 7d, 30d, 90d).",
              "schema": {
                "example": "6h,24h,7d,13d",
                "type": "string"
              }
            }
          ],
          "responses": {
            "200": {
              "description": "Measurement averages for multiple time periods",
              "content": {
                "application/json": {
                  "schema": {
                    "$ref": "#/components/schemas/MeasurementAveragesDto"
                  }
                }
              }
            },
            "400": {
              "description": "Invalid location ID format or measure type"
            },
            "404": {
              "description": "Location not found or no measurement data available"
            }
          },
          "summary": "Get measurement averages for a location",
          "tags": [
            "Locations"
          ]
        }
      },
      "/map/api/v1/locations/{id}/measures/history": {
        "get": {
          "description": "Retrieve time-series data for a specific location within a date range. Supports various bucket sizes for data aggregation.",
          "operationId": "LocationController_getmeasuresHistoryByLocationId",
          "parameters": [
            {
              "name": "id",
              "required": true,
              "in": "path",
              "description": "Location identifier",
              "schema": {
                "example": 12345,
                "type": "number"
              }
            },
            {
              "name": "measure",
              "required": false,
              "in": "query",
              "description": "Type of measurement to filter by",
              "schema": {
                "type": "string",
                "enum": [
                  "pm25",
                  "pm10",
                  "atmp",
                  "rhum",
                  "rco2",
                  "o3",
                  "no2"
                ]
              }
            },
            {
              "name": "start",
              "required": true,
              "in": "query",
              "description": "Start date in ISO 8601 format with timezone (eg. 2025-08-30T20:01:00-04:00)",
              "schema": {
                "default": "2025-08-30T20:01:00.000Z",
                "type": "string"
              }
            },
            {
              "name": "end",
              "required": true,
              "in": "query",
              "description": "End date in ISO 8601 format with timezone (eg. 2025-08-30T20:01:00-04:00)",
              "schema": {
                "default": "2025-08-30T20:01:00.000Z",
                "type": "string"
              }
            },
            {
              "name": "bucketSize",
              "required": true,
              "in": "query",
              "description": "Size of bucket for data aggregation. For 1w, weeks always start on Mondays",
              "schema": {
                "type": "string",
                "enum": [
                  "15m",
                  "1h",
                  "8h",
                  "1d",
                  "1w",
                  "1M",
                  "1y"
                ]
              }
            }
          ],
          "responses": {
            "200": {
              "description": "",
              "content": {
                "application/json": {
                  "schema": {
                    "allOf": [
                      {
                        "$ref": "#/components/schemas/Pagination"
                      },
                      {
                        "properties": {
                          "data": {
                            "type": "array",
                            "items": {
                              "$ref": "#/components/schemas/Timeseries"
                            }
                          }
                        }
                      }
                    ]
                  }
                }
              }
            },
            "400": {
              "description": "Invalid date format, bucket size, or date range"
            },
            "404": {
              "description": "Location not found"
            }
          },
          "summary": "Get historical measurements for a location",
          "tags": [
            "Locations"
          ]
        }
      },
      "/map/api/v1/wind-data/current": {
        "get": {
          "description": "\n      Retrieves the latest GFS wind forecast data within the specified bounding box.\n      Data is returned in an optimized grid format with U and V wind components.\n\n      Grid format:\n      - Data ordered north-to-south, west-to-east\n      - Index calculation: index = y * nx + x\n      - U-component: eastward wind (m/s)\n      - V-component: northward wind (m/s)\n\n      Compatible with leaflet-velocity library via simple transformation.\n    ",
          "operationId": "WindDataController_getCurrentWindData",
          "parameters": [
            {
              "name": "xmin",
              "required": true,
              "in": "query",
              "description": "Minimum longitude (western bound)",
              "schema": {
                "example": -10,
                "type": "number"
              }
            },
            {
              "name": "xmax",
              "required": true,
              "in": "query",
              "description": "Maximum longitude (eastern bound)",
              "schema": {
                "example": 40,
                "type": "number"
              }
            },
            {
              "name": "ymin",
              "required": true,
              "in": "query",
              "description": "Minimum latitude (southern bound)",
              "schema": {
                "example": 35,
                "type": "number"
              }
            },
            {
              "name": "ymax",
              "required": true,
              "in": "query",
              "description": "Maximum latitude (northern bound)",
              "schema": {
                "example": 70,
                "type": "number"
              }
            }
          ],
          "responses": {
            "200": {
              "description": "Wind data retrieved successfully",
              "content": {
                "application/json": {
                  "schema": {
                    "$ref": "#/components/schemas/WindDataEntity"
                  }
                }
              }
            }
          },
          "summary": "Get current wind forecast data for a geographic area",
          "tags": [
            "Wind Data"
          ]
        }
      },
      "/map/api/v1/fires-data/current": {
        "get": {
          "description": "\n      Retrieves NASA FIRMS wildfire detection data within the specified bounding box.\n      Data includes MODIS NRT fire detections with confidence values and fire radiative power.\n\n      Features:\n      - Fire location, carried by geometry.coordinates as [longitude, latitude]\n      - Raw confidence value from the FIRMS feed, which each client buckets itself\n      - Optional minimum confidence filtering in the database query\n      - Fire Radiative Power (FRP) in megawatts, null when the feed omitted it\n\n      The acquisition date, acquisition time and satellite are no longer returned.\n\n      Data is returned in GeoJSON FeatureCollection format for easy mapping.\n      Feature order is not part of the contract, clustered or not. Sort client-side if\n      you need one; the API takes no view on confidence and so cannot order by it.\n\n      A cluster carries its count and the zoom it splits at, and nothing else. It is\n      not summarised by confidence, FRP or recency: read those from the individual\n      detections a cluster resolves to when you zoom in.\n\n      Clustering:\n      - Pass 'zoom' to receive dense areas aggregated into clusters. Omit it and every\n        detection is returned individually, which is what clients built before\n        clustering do. Note that only the aggregation is opt-in: the trimmed property\n        set above applies to every response, clustered or not.\n      - Clusters are selected by their centre. A cluster whose centre falls just\n        outside the requested bbox is not returned, even when some of its detections\n        are inside it. This matches how the sensor layer answers a viewport; padding\n        the lookup was tried and does not fix it, because a detection can sit further\n        from its cluster's centre than any fixed pad.\n      - A returned cluster can still aggregate detections from just outside the bbox,\n        because the underlying query is widened by a fixed buffer for edge coverage.\n        'fireCount' is therefore not a count of what is strictly in view.\n      - A clustered response is a mix. A feature carrying 'fireCount' is a cluster; a\n        feature without it is a single detection and still carries confidence and frp.\n        An isolated detection is never wrapped in a cluster of one.\n      - A cluster also carries 'expansionZoom', the zoom at which it breaks into its\n        children. Move the map there when the user taps it and the cluster is\n        guaranteed to split; guessing a zoom step instead can land short and leave the\n        same cluster on screen.\n      - Above the clustering gate the response is individual detections regardless.\n      - 'count' remains the number of detections, so on a clustered response it is\n        larger than features.length.\n    ",
          "operationId": "FiresDataController_getCurrentFiresData",
          "parameters": [
            {
              "name": "xmin",
              "required": true,
              "in": "query",
              "description": "Minimum longitude (western bound)",
              "schema": {
                "example": -125,
                "type": "number"
              }
            },
            {
              "name": "xmax",
              "required": true,
              "in": "query",
              "description": "Maximum longitude (eastern bound)",
              "schema": {
                "example": -114,
                "type": "number"
              }
            },
            {
              "name": "ymin",
              "required": true,
              "in": "query",
              "description": "Minimum latitude (southern bound)",
              "schema": {
                "example": 32,
                "type": "number"
              }
            },
            {
              "name": "ymax",
              "required": true,
              "in": "query",
              "description": "Maximum latitude (northern bound)",
              "schema": {
                "example": 42,
                "type": "number"
              }
            },
            {
              "name": "hours",
              "required": false,
              "in": "query",
              "description": "Time range in hours (default: 24, max: 168)",
              "schema": {
                "example": 24,
                "type": "number"
              }
            },
            {
              "name": "minConfidence",
              "required": false,
              "in": "query",
              "description": "Minimum FIRMS confidence score to include (0-100)",
              "schema": {
                "example": 80,
                "type": "number"
              }
            },
            {
              "name": "zoom",
              "required": false,
              "in": "query",
              "description": "Map zoom level. When given and at or below the clustering gate, detections are returned aggregated into clusters carrying fireCount. Omit it to receive every detection individually, which is what clients built before clustering do.",
              "schema": {
                "example": 3,
                "type": "number"
              }
            }
          ],
          "responses": {
            "200": {
              "description": "Fires data retrieved successfully",
              "content": {
                "application/json": {
                  "schema": {
                    "$ref": "#/components/schemas/FiresDataEntity"
                  }
                }
              }
            }
          },
          "summary": "Get current wildfire detection data for a geographic area",
          "tags": [
            "Fires Data"
          ]
        }
      },
