    "info": {
      "title": "AirGradient Map API",
      "description": "\n**AirGradient Map API** - Access real-time and historical air quality data from the global AirGradient monitoring network.\n\nAirGradient publishes measurements from AirGradient monitors and third-party data owners. Datasource, owner, provider, and location license metadata explain attribution and reuse context. Keep those fields visible when displaying or redistributing API data.\n\nSome datasources are available only inside AirGradient products under provider agreements and are not exposed through the public API. Public API availability does not grant reuse rights. Users remain responsible for following datasource owner terms and any licenses attached to each location.\n\nIf a location has no listed license, no explicit license has been stored for that location. It does not mean the data is unrestricted.\n",
      "version": "1.0",
      "contact": {
        "name": "AirGradient Support",
        "url": "https://www.airgradient.com/support/",
        "email": "support@airgradient.com"
      }
    },
    "tags": [
      {
        "name": "Catalog",
        "description": "API master lists for datasources, licenses, measurements, coordinate system metadata, notification types, and monitor types."
      },
      {
        "name": "Measurements",
        "description": "Current and historical air quality measurements"
      },
      {
        "name": "Locations",
        "description": "Information about monitoring locations and sensors"
      }
    ],
    "servers": [
      {
        "url": "https://map-data.airgradient.com",
        "description": "Production Server"
      }
    ],
    "components": {
      "securitySchemes": {
        "data-permission-context": {
          "type": "apiKey",
          "in": "header",
          "name": "data-permission-context"
        }
      },
      "schemas": {
        "Pagination": {
          "type": "object",
          "properties": {
            "data": {
              "type": "array",
              "items": {
                "type": "string"
              }
            },
            "total": {
              "type": "number"
            },
            "page": {
              "type": "number"
            },
            "pagesize": {
              "type": "number"
            }
          },
          "required": [
            "data",
            "total",
            "page",
            "pagesize"
          ]
        },
        "MeasurementEntity": {
          "type": "object",
          "properties": {
            "locationId": {
              "type": "number"
            },
            "locationName": {
              "type": "string"
            },
            "longitude": {
              "type": "number"
            },
            "latitude": {
              "type": "number"
            },
            "sensorType": {
              "type": "string"
            },
            "pm25": {
              "type": "number"
            },
            "pm10": {
              "type": "number"
            },
            "atmp": {
              "type": "number"
            },
            "rhum": {
              "type": "number"
            },
            "rco2": {
              "type": "number"
            },
            "o3": {
              "type": "number"
            },
            "no2": {
              "type": "number"
            },
            "measuredAt": {
              "format": "date-time",
              "type": "string"
            },
            "dataSource": {
              "type": "string"
            }
          },
          "required": [
            "locationId",
            "locationName",
            "longitude",
            "latitude",
            "sensorType",
            "measuredAt",
            "dataSource"
          ]
        },
        "MeasurementCluster": {
          "type": "object",
          "properties": {
